{
  "wire_schema": "role_benchmark.player_action.v3",
  "kind": "experiment",
  "portfolio": {
    "hypotheses": [
      {
        "hypothesis_id": "H1_length",
        "statement": "T = 2*pi*sqrt(L/g) with g=9.81 m/s^2; period depends only on length.",
        "confidence": 0.4
      },
      {
        "hypothesis_id": "H2_mass",
        "statement": "T = 2*pi*sqrt(L/g)*(1 + m); period increases linearly with bob mass.",
        "confidence": 0.3
      },
      {
        "hypothesis_id": "H3_angle",
        "statement": "T = 2*pi*sqrt(L/g)*(1 + 0.02*theta_deg); period increases linearly with release angle.",
        "confidence": 0.3
      }
    ]
  },
  "experiment": {
    "intent": "Measure period at a fixed length and moderate angle while using a heavy bob to test whether bob mass affects period.",
    "apparatus": "simple_pendulum",
    "controls": {
      "length_m": 1.0,
      "bob_mass_kg": 1.0,
      "release_angle_deg": 5.0
    },
    "readouts": ["period_s"],
    "replicates": 5,
    "forecasts": {
      "H1_length": {"period_s": 2.0064},
      "H2_mass": {"period_s": 4.0128},
      "H3_angle": {"period_s": 2.2070}
    }
  },
  "final": null
}

{
  "wire_schema": "role_benchmark.player_action.v3",
  "kind": "experiment",
  "portfolio": {
    "hypotheses": [
      {
        "hypothesis_id": "H_L_only",
        "statement": "T = 3 * sqrt(length_m); period depends only on length, not on bob mass or release angle.",
        "confidence": 0.55
      },
      {
        "hypothesis_id": "H_mass_linear",
        "statement": "T = 3 * sqrt(length_m) * bob_mass_kg; period is directly proportional to bob mass.",
        "confidence": 0.25
      },
      {
        "hypothesis_id": "H_mass_inverse",
        "statement": "T = 3 * sqrt(length_m) / bob_mass_kg; period is inversely proportional to bob mass.",
        "confidence": 0.2
      }
    ]
  },
  "experiment": {
    "intent": "Hold length and release angle at the baseline values, halve the bob mass, and measure the period to distinguish mass independence, direct mass proportionality, and inverse mass proportionality.",
    "apparatus": "simple_pendulum",
    "controls": {
      "length_m": 1.0,
      "bob_mass_kg": 0.5,
      "release_angle_deg": 5.0
    },
    "readouts": ["period_s"],
    "replicates": 5,
    "forecasts": {
      "H_L_only": {"period_s": 3.0},
      "H_mass_linear": {"period_s": 1.5},
      "H_mass_inverse": {"period_s": 6.0}
    }
  },
  "final": null
}

